public class Solution {
    static class Result {
        long g, x, y;
        Result(long g, long x, long y) { this.g = g; this.x = x; this.y = y; }
    }
    public static Result extGCD(long a, long b) {
        if (b == 0) return new Result(a, 1, 0);
        Result res = extGCD(b, a % b);
        long x = res.y;
        long y = res.x - (a / b) * res.y;
        return new Result(res.g, x, y);
    }
    public static long modInverse(long a, long m) {
        Result res = extGCD(a, m);
        if (res.g != 1) return -1;
        return (res.x % m + m) % m;
    }
}

function extGCD(a, b) {
  if (b === 0) return { g: a, x: 1, y: 0 };
  const res = extGCD(b, a % b);
  const x = res.y;
  const y = res.x - Math.floor(a / b) * res.y;
  return { g: res.g, x, y };
}

function modInverse(a, m) {
  const res = extGCD(a, m);
  if (res.g !== 1) return -1;
  return (res.x % m + m) % m;
}

