def segmented_sieve(L: int, R: int) -> list[int]:
    limit = int(R**0.5) + 1
    # Step 1: Base primes
    is_prime_base = [True] * (limit + 1)
    is_prime_base[0] = is_prime_base[1] = False
    for p in range(2, int(limit**0.5) + 1):
        if is_prime_base[p]:
            for i in range(p * p, limit + 1, p):
                is_prime_base[i] = False
    base_primes = [i for i in range(2, limit + 1) if is_prime_base[i]]

    # Step 2: Segmented array for [L, R]
    dummy = [True] * (R - L + 1)
    for p in base_primes:
        first_multiple = max(p * p, ((L + p - 1) // p) * p)
        for j in range(first_multiple, R + 1, p):
            dummy[j - L] = False

    primes = []
    for i in range(R - L + 1):
        if dummy[i] and (i + L) >= 2:
            primes.append(i + L)
    return primes

