function segmentedSieve(L, R) {
  const limit = Math.floor(Math.sqrt(R)) + 1;
  const isBasePrime = new Array(limit + 1).fill(true);
  isBasePrime[0] = isBasePrime[1] = false;
  for (let p = 2; p * p <= limit; p++) {
    if (isBasePrime[p]) {
      for (let i = p * p; i <= limit; i += p) isBasePrime[i] = false;
    }
  }
  const basePrimes = [];
  for (let i = 2; i <= limit; i++) if (isBasePrime[i]) basePrimes.push(i);

  const dummy = new Array(R - L + 1).fill(true);
  for (const p of basePrimes) {
    let firstMultiple = Math.max(p * p, Math.ceil(L / p) * p);
    for (let j = firstMultiple; j <= R; j += p) {
      dummy[j - L] = false;
    }
  }
  const primes = [];
  for (let i = 0; i <= R - L; i++) {
    if (dummy[i] && (i + L) >= 2) primes.push(i + L);
  }
  return primes;
}

