class LinearSieve {
  constructor(n) {
    this.spf = Array.from({ length: n + 1 }, (_, i) => i);
    this.primes = [];
    for (let i = 2; i <= n; i++) {
      if (this.spf[i] === i) this.primes.push(i);
      for (const p of this.primes) {
        if (p > this.spf[i] || i * p > n) break;
        this.spf[i * p] = p;
      }
    }
  }
  getPrimeFactors(n) {
    const factors = [];
    while (n > 1) {
      factors.push(this.spf[n]);
      n = Math.floor(n / this.spf[n]);
    }
    return factors;
  }
}
